# Material Symbols "api" icon (Apache-2.0), used for the REST API concept rather
# than a logo belonging to a specific API standard or organization.
MATERIAL_SYMBOL_PATHS = {
    "restapis": "m480-400-80-80 80-80 80 80-80 80Zm-85-235L295-735l185-185 185 185-100 100-85-85-85 85ZM225-295 40-480l185-185 100 100-85 85 85 85-100 100Zm510 0L635-395l85-85-85-85 100-100 185 185-185 185ZM480-40 295-225l100-100 85 85 85-85 100 100L480-40Z",
}

def esc(value: Any) -> str:
    return html.escape(str(value or ""), quote=True)

def load_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))

def write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content.rstrip() + "\n", encoding="utf-8")

def svg_shell(width: int, height: int, title: str, body: str) -> str:
    # Crop the generous vertical canvas padding while retaining a slightly
    # larger breathing room above the profile content than below it.
    top_crop = 120
    bottom_crop = 28
    visible_height = height - top_crop - bottom_crop
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{visible_height}" viewBox="0 {top_crop} {width} {visible_height}" role="img" aria-label="{esc(title)}">
{body}
</svg>'''

def skill_icon(skill: str, x: int, y: int, stroke: str) -> str:
    key = re.sub(r"[^a-z0-9]+", "", skill.lower())
    aliases = {
        "spring": "springboot",
        "restapi": "restapis",
        "api": "restapis",
        "apis": "restapis",
        "postgres": "postgresql",
        "sql": "postgresql",
        "database": "postgresql",
    }
    icon_key = aliases.get(key, key)
    material_path = MATERIAL_SYMBOL_PATHS.get(icon_key)
    if material_path:
        return (
            f'<g transform="translate({x} {y + 30}) scale(.03125)" fill="{stroke}">'
            f'<path d="{material_path}"/>'
            "</g>"
        )

    path = SIMPLE_ICON_PATHS.get(icon_key)
    if not path:
        return ""
    return (
        f'<g transform="translate({x} {y}) scale(1.25)" fill="{stroke}">'
        f'<path d="{path}"/>'
        "</g>"
    )

def render_profile(config: dict[str, Any], theme: dict[str, str]) -> str:
    intro = " ".join(str(config.get("intro", "")).split())
    intro_lines = [intro] if intro else []
    intro_tspans = "\n".join(
        f'    <tspan x="64" dy="{0 if i == 0 else 39}">{esc(line)}</tspan>'
        for i, line in enumerate(intro_lines)
    )
    name = esc(config.get("name", ""))
    role = esc(config.get("role", ""))
    eyebrow = esc(config.get("eyebrow", "HELLO, WORLD!"))
    skills = [str(x) for x in config.get("learning", [])][:12]
    cols = 3
    rows = max(1, (len(skills) + cols - 1) // cols)
    learning_top = 600
    height = learning_top + 112 + rows * 92 + 38
    card_w = 344
    card_h = 74
    x_positions = [64, 428, 792]

    pieces = [
        f'''  <text x="64" y="205" fill="{theme["accent"]}" font-family="Arial, Helvetica, sans-serif"
        font-size="16" font-weight="700" letter-spacing="5">{eyebrow}</text>
  <line x1="262" y1="199" x2="332" y2="199" stroke="{theme["line"]}" stroke-width="1"/>

  <text x="64" y="360" fill="{theme["text"]}" font-family="Arial, Helvetica, sans-serif"
        font-size="78" font-weight="300" letter-spacing="-3">I'm {name}.</text>

  <text x="64" y="442" fill="{theme["soft"]}" font-family="Georgia, 'Times New Roman', serif"
        font-size="64" font-style="italic" font-weight="700" letter-spacing="-3">{role}</text>

  <text x="64" y="522" fill="{theme["muted"]}" font-family="Arial, Helvetica, sans-serif"
        font-size="22" font-weight="400">
{intro_tspans}
  </text>

  <text x="64" y="{learning_top + 72}" fill="{theme["muted"]}" font-family="Arial, Helvetica, sans-serif"
        font-size="16" font-weight="700" letter-spacing="5">CURRENTLY LEARNING</text>''',
        f'  <line x1="340" y1="{learning_top + 66}" x2="1136" y2="{learning_top + 66}" stroke="{theme["line"]}" stroke-width="1"/>'
    ]

    for i, skill in enumerate(skills):
        row, col = divmod(i, cols)
        x = x_positions[col]
        y = learning_top + 98 + row * 92
        pieces.append(
            f'  <rect x="{x}" y="{y}" width="{card_w}" height="{card_h}" rx="18" '
            f'fill="none" stroke="{theme["border"]}" stroke-width="1"/>'
        )
        icon = skill_icon(skill, x + 22, y + 23, theme["soft"])
        pieces.append(icon)
        label_x = x + 61 if icon else x + 22
        pieces.append(
            f'  <text x="{label_x}" y="{y+45}" fill="{theme["muted"]}" '
            f'font-family="Arial, Helvetica, sans-serif" font-size="17">{esc(skill)}</text>'
        )

    if not skills:
        pieces.append(
            f'  <text x="64" y="{learning_top + 135}" fill="{theme["soft"]}" font-family="Arial, Helvetica, sans-serif" '
            f'font-size="18">Add skills in profile.json</text>'
        )

    title = f'{config.get("name", "")} — {config.get("role", "")}. Currently learning.'
    return svg_shell(1200, height, title, "\n".join(pieces))

def picture_html(dark: str, light: str, alt: str) -> str:
    return f'''<picture>
  <source media="(prefers-color-scheme: dark)" srcset="{dark}">
  <source media="(prefers-color-scheme: light)" srcset="{light}">
  <img src="{dark}" width="100%" alt="{esc(alt)}">
</picture>'''

def generate_readme(config: dict[str, Any]) -> str:
    chunks = [
        "<!--",
        "  AUTO-GENERATED FILE.",
        "  Edit profile.json or scripts/generate_profile.py instead.",
        "-->",
        "",
        picture_html(
            "./assets/profile-dark.svg",
            "./assets/profile-light.svg",
            f'{config.get("name", "")} — {config.get("role", "")}. Currently learning.',
        ),
        "",
    ]

    return "\n".join(chunks)

def main() -> int:
    config = load_json(CONFIG_PATH)

    ASSETS.mkdir(parents=True, exist_ok=True)

    for old in (*ASSETS.glob("hero-*.svg"), *ASSETS.glob("learning-*.svg")):
        old.unlink()

    for theme_name, theme in THEMES.items():
        write(ASSETS / f"profile-{theme_name}.svg", render_profile(config, theme))

    write(ROOT / "README.md", generate_readme(config))

    print(f"Generated profile for: {config.get('name', '')}")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
